create table public.exam_attempts (id uuid primary key default gen_random_uuid(), exam_id uuid not null references public.exams(id) on delete restrict, student_id uuid not null references public.profiles(id) on delete restrict, started_at timestamptz not null default now(), submitted_at timestamptz, response jsonb, score numeric(6,2) check (score between 0 and 100), result jsonb, status text not null default 'started', created_at timestamptz not null default now(), updated_at timestamptz not null default now());;
